// =====================================================================
// BLOQUES S1 / C0 · Inicializacion (comun a ambas placas)
// diagramas/flujo_servidor.md S1 · diagramas/flujo_cliente.md C0
// ---------------------------------------------------------------------
// Descripcion: se ejecuta una vez al desplegar el flujo. Verifica que
//   settings.js haya cargado los modulos compartidos y que config.js sea
//   la version que este flujo espera, y lleva los dos LED a su estado
//   seguro (apagados) antes de que exista cualquier dato.
// Entrada: msg del inject de arranque; msg.payload = nombre del modulo
//   OPC UA que esta placa necesita ('servidorOpcua' | 'clienteOpcua').
// Salidas: [1] LED digital (payload 0) · [2] LED PWM (payload 0 %).
// Excepciones: si falta un modulo, informa con node.error() y no envia
//   nada: un nodo mal desplegado avisa, no se comporta a medias.
// =====================================================================
const VERSION_CONFIG_REQUERIDA = 1;

const config = global.get('config');
const senales = global.get('senales');
const faltantes = ['config', 'senales', 'opcua', 'pdciRutas', String(msg.payload)].filter((n) => !global.get(n));
if (faltantes.length > 0) {
    node.error('settings.js no cargo: ' + faltantes.join(', ') + ' (ver node-red/README.md §3)');
    node.status({ fill: 'red', shape: 'dot', text: 'falta ' + faltantes.join(', ') });
    return null;
}
if (config.VERSION !== VERSION_CONFIG_REQUERIDA) {
    // Igual que en la Tarea 1: un nodo con configuracion vieja arranca
    // avisando, no aborta.
    node.warn('config.js version ' + config.VERSION + ', este flujo espera ' + VERSION_CONFIG_REQUERIDA);
}
node.status({ fill: 'green', shape: 'dot', text: 'config v' + config.VERSION });
return [{ payload: 0 }, { payload: senales.dutyAPorcentajePiGpiod(0) }];

// =====================================================================
// BLOQUE C2 · Rampa triangular — Raspberry Pi 2
// diagramas/flujo_cliente.md, bloque C2 · consigna Parte 3.2
// ---------------------------------------------------------------------
// Descripcion: cada 50 ms calcula la rampa triangular 0-65535 de periodo
//   8 s (4 s de subida, 4 s de bajada) a partir del reloj. Solo actualiza
//   el contexto: la escritura en Cliente.Rampa la hace C5 cada 100 ms, que
//   es la tasa que pide la consigna (generar a 50 ms, escribir a 100 ms).
// Entrada: msg del inject "C2 · Tick".
// Salida: ninguna.
// Excepciones: ninguna.
//
// Firma: senales.triangular(tMs: number, periodoMs: number, tickMs: number,
//   maximo?: number) : number
// =====================================================================
const config = global.get('config');
const senales = global.get('senales');
const valor = senales.triangular(Date.now(), config.senales.periodoTriangularMs, config.senales.tickMs,
    config.senales.maximo);
flow.set('rampaGenerada', valor);
return null;

// =====================================================================
// BLOQUE C5 · Escritura periodica de la rampa — Raspberry Pi 2
// diagramas/flujo_cliente.md, bloque C5 · consigna Parte 3.3
// ---------------------------------------------------------------------
// Descripcion: cada 100 ms toma el ultimo valor de la rampa local (C2) y
//   lo envia a C1 para escribirlo en Cliente.Rampa.
//   Los botones "C5 · Detener rampa" / "C5 · Reanudar rampa" envian
//   msg.topic = 'pausa' (true/false): detenida, no se escribe nada, asi la
//   captura de KeepAlive de la Parte 3.4 queda sin Writes intercalados.
// Entrada: msg del inject "C5 · Cada 100 ms", o { topic: 'pausa', payload }.
// Salida: { topic: 'rampa', payload: UInt16 } -> C1.
// Excepciones: si C2 todavia no genero ningun valor, no se envia nada.
// =====================================================================
if (msg.topic === 'pausa') {
    const pausada = msg.payload === true;
    flow.set('rampaPausada', pausada);
    node.status(pausada ? { fill: 'grey', shape: 'ring', text: 'escritura detenida' } : {});
    node.log(new Date().toISOString() + ' escritura de rampa ' + (pausada ? 'DETENIDA' : 'reanudada'));
    return null;
}
if (flow.get('rampaPausada')) return null;
const valor = flow.get('rampaGenerada');
if (valor === undefined) return null;
return { topic: 'rampa', payload: valor };

// =====================================================================
// BLOQUES S4 / C5 · Lectura del pulsador local (comun a ambas placas)
// diagramas/flujo_servidor.md S4 · diagramas/flujo_cliente.md C5
// ---------------------------------------------------------------------
// Descripcion: convierte el nivel del GPIO en el Boolean del modelo. El
//   pulsador va a GND con pull-up interno: nivel 0 = presionado. El
//   antirrebote lo hace pigpio (set_glitch_filter, 25 000 us) antes de que
//   llegue el mensaje.
// Entrada: msg.payload 0 | 1 desde "pi gpiod in" (un mensaje por flanco).
// Salida: { topic: 'pulsador', payload: boolean, instante: Date }
//   -> S2 (servidor: publica Servidor.EstadoPulsador)
//   -> C1 (cliente: escribe Cliente.EstadoPulsador)
// Registro: una linea 'LATENCIA pulsador_local=...' por flanco.
// Excepciones: un payload que no sea 0/1 se descarta con advertencia.
// =====================================================================
const nivel = Number(msg.payload);
if (nivel !== 0 && nivel !== 1) {
    node.warn('nivel GPIO invalido: ' + msg.payload);
    return null;
}
const presionado = nivel === 0; // activo en bajo
const instante = new Date();
flow.set('pulsadorLocal', presionado);
// Marca para medir la latencia pulsador -> LED de la otra placa (Parte 3.4):
// se compara con la linea "LED digital" del otro equipo, con los relojes
// sincronizados por chrony (node-red/README.md §14).
node.log('LATENCIA pulsador_local=' + (presionado ? 'ON' : 'OFF') + ' t=' + instante.toISOString());
return { topic: 'pulsador', payload: presionado, instante };

// =====================================================================
// BLOQUE C5 -> C1 · Escrituras del cliente
// diagramas/flujo_cliente.md, bloque C5 · consigna Parte 3.3
// ---------------------------------------------------------------------
// Descripcion: escribe el pulsador local en Cliente.EstadoPulsador y la
//   rampa local en Cliente.Rampa. Si no hay conexion, o el Write anterior
//   de esa variable sigue pendiente, la escritura se omite y se cuenta: al
//   reconectar se escribe el valor vigente, no una cola de valores viejos.
// Entrada: msg.topic 'pulsador' (boolean) | 'rampa' (0-65535).
// Salida: ninguna.
// Excepciones: los errores de escritura llegan como evento por la salida 2
//   (write_error) desde cliente_opcua.js.
// =====================================================================
const controlador = context.get('controlador');
if (!controlador) {
    context.set('omitidasSinConexion', (context.get('omitidasSinConexion') || 0) + 1);
    return null;
}
if (msg.topic === 'pulsador') {
    controlador.escribirPulsador(msg.payload === true).then((sc) => {
        if (sc && sc !== 'Good') node.warn('Write Cliente.EstadoPulsador -> ' + sc);
    });
} else if (msg.topic === 'rampa') {
    controlador.escribirRampa(msg.payload).then((sc) => {
        if (sc && sc !== 'Good') node.warn('Write Cliente.Rampa -> ' + sc);
    });
}
return null;

initialize:
// =====================================================================
// BLOQUES C1, C3 y C7 · Cliente OPC UA — "On Start" de la function node
// diagramas/flujo_cliente.md, bloques C1 (conexion), C3a/C3b (lectura)
// y C7 (perdida y recuperacion del canal)
// ---------------------------------------------------------------------
// Descripcion: arranca el cliente con cliente_opcua.iniciarCliente() EN
//   SEGUNDO PLANO, sin await. Si On Start esperara la conexion y la RPi 1
//   estuviera apagada, Node-RED encolaria los 20 mensajes por segundo de
//   los temporizadores hasta que el servidor aparezca. Asi, el nodo queda
//   listo enseguida y descarta (y cuenta) lo que llega sin conexion.
// Salidas: [1] dato recibido { topic: 'servidorPulsador'|'servidorRampa',
//               payload, sourceTimestamp, serverTimestamp, statusCode }
//          [2] evento de conexion/sesion/suscripcion { topic, payload }
// Excepciones: si el primer intento falla (servidor caido, certificado no
//   confiado), reintenta cada 5 s y lo informa en el estado del nodo.
//
// Firma de la biblioteca:
//   iniciarCliente({ opcua: object, config: object, directorioPki: string,
//     alRecibir: (dato: object) => void, alEvento: (evento: object) => void,
//     entorno?: object }) : Promise<Controlador>
// =====================================================================
const config = global.get('config');
const opcua = global.get('opcua');
const modulo = global.get('clienteOpcua');
const rutas = global.get('pdciRutas');

context.set('activo', true);

const alRecibir = (dato) => {
    node.send([{
        topic: dato.variable, payload: dato.valor, statusCode: dato.statusCode,
        sourceTimestamp: dato.sourceTimestamp, serverTimestamp: dato.serverTimestamp, modo: dato.modo,
    }, null]);
};
const alEvento = (e) => {
    const texto = e.evento + (e.statusCode ? ' StatusCode=' + e.statusCode : '') + (e.detalle ? ' ' + e.detalle : '');
    node.send([null, { topic: e.evento, payload: texto, statusCode: e.statusCode }]);
};

const conectar = () => {
    if (!context.get('activo')) return;
    node.status({ fill: 'yellow', shape: 'ring', text: 'conectando a ' + config.opcua.endpointCliente });
    modulo.iniciarCliente({ opcua, config, directorioPki: rutas.pkiCliente, alRecibir, alEvento })
        .then((controlador) => {
            if (!context.get('activo')) { controlador.detener(); return; }
            context.set('controlador', controlador);
            node.status({ fill: 'green', shape: 'dot', text: 'Modo ' + config.lectura.modo + ' ' +
                config.seguridad.modoCliente + '/' + config.seguridad.politicaCliente });
        })
        .catch((error) => {
            node.status({ fill: 'red', shape: 'dot', text: error.message });
            node.warn('conexion fallida, reintento en 5 s: ' + error.message);
            context.set('reintento', setTimeout(conectar, 5000));
        });
};
conectar();

finalize:
// =====================================================================
// BLOQUE C1 · Cliente OPC UA — "On Close" de la function node
// ---------------------------------------------------------------------
// Descripcion: al redesplegar o detener Node-RED cierra la sesion de forma
//   ordenada (CloseSession + CLO + FIN de TCP), cancela un reintento
//   pendiente y marca el nodo como inactivo para que una conexion que
//   termine despues no quede viva.
// =====================================================================
context.set('activo', false);
const reintento = context.get('reintento');
if (reintento) clearTimeout(reintento);
const controlador = context.get('controlador');
if (controlador) {
    controlador.detener().catch((e) => node.warn('cierre del cliente: ' + e.message));
    context.set('controlador', undefined);
}

func:
// =====================================================================
// BLOQUE C4 · Manejo de notificaciones y respuestas — Raspberry Pi 2
// diagramas/flujo_cliente.md, bloque C4 · consigna Parte 3.3
// ---------------------------------------------------------------------
// Descripcion: recibe cada dato leido del servidor (por Read en Modo A o
//   por notificacion en Modo B; el resto del flujo no distingue) y lo
//   dirige al LED correspondiente. Guarda el ultimo valor y su
//   SourceTimestamp para la consola (C6).
// Entrada: msg.topic 'servidorPulsador' | 'servidorRampa', msg.payload,
//   msg.statusCode, msg.sourceTimestamp.
// Salidas: [1] -> LED digital · [2] -> LED PWM.
// Excepciones: un dato con StatusCode distinto de Good NO se aplica a los
//   LED: se conserva el ultimo valor bueno (el LED se congela, igual que
//   con el cable desconectado).
// =====================================================================
if (msg.statusCode && msg.statusCode !== 'Good') {
    node.status({ fill: 'yellow', shape: 'ring', text: msg.topic + ' ' + msg.statusCode });
    return null;
}
flow.set(msg.topic, { valor: msg.payload, sourceTimestamp: msg.sourceTimestamp, modo: msg.modo });
if (msg.topic === 'servidorPulsador') return [{ payload: msg.payload }, null];
if (msg.topic === 'servidorRampa') return [null, { payload: msg.payload }];
return null;

// =====================================================================
// BLOQUES S6 / C4 · LED digital (comun a ambas placas)
// diagramas/flujo_servidor.md S6 · diagramas/flujo_cliente.md C4
// ---------------------------------------------------------------------
// Descripcion: el LED digital refleja el EstadoPulsador del OTRO equipo
//   (servidor: Cliente.EstadoPulsador; cliente: Servidor.EstadoPulsador).
// Entrada: msg.payload boolean.
// Salida: msg.payload 1 | 0 -> "pi gpiod out" en modo digital.
// Registro: una linea 'LATENCIA led_digital=...' por cada cambio.
// Excepciones: un payload que no sea boolean se descarta: nunca se
//   enciende un actuador con un dato de tipo dudoso.
// =====================================================================
if (msg.payload !== true && msg.payload !== false) {
    node.warn('EstadoPulsador no booleano: ' + msg.payload);
    return null;
}
node.status({ fill: msg.payload ? 'green' : 'grey', shape: 'dot', text: msg.payload ? 'ON' : 'OFF' });
// Marca para medir la latencia (Parte 3.4): solo cuando el LED CAMBIA. En
// Modo A llega el mismo valor 10 veces por segundo; registrar cada uno
// inundaria el registro y no aporta nada.
if (context.get('ultimo') !== msg.payload) {
    context.set('ultimo', msg.payload);
    node.log('LATENCIA led_digital=' + (msg.payload ? 'ON' : 'OFF') + ' t=' + new Date().toISOString());
}
return { payload: msg.payload ? 1 : 0 };

// =====================================================================
// BLOQUES S6 / C4 · LED PWM (comun a ambas placas)
// diagramas/flujo_servidor.md S6 · diagramas/flujo_cliente.md C4
// consigna Partes 2.4 y 3.7
// ---------------------------------------------------------------------
// Descripcion: escala la Rampa recibida del OTRO equipo (UInt16) a ciclo
//   de trabajo 0-255, con correccion gamma opcional (config.senales), y
//   la convierte al porcentaje que espera "pi gpiod out" en modo PWM.
// Entrada: msg.payload entero 0-65535.
// Salida: msg.payload porcentaje 0-100 (exacto para pigpio, ver
//   senales.dutyAPorcentajePiGpiod); msg.duty con el 0-255 para la traza.
// Excepciones: un valor fuera de rango se descarta con advertencia.
//
// Firmas: senales.escala255(valor: number, maximo?: number,
//   gamma?: number) : number · senales.dutyAPorcentajePiGpiod(duty: number)
//   : number
// =====================================================================
const config = global.get('config');
const senales = global.get('senales');
if (!senales.esUInt16(msg.payload)) {
    node.warn('Rampa fuera de rango: ' + msg.payload);
    return null;
}
const gamma = config.senales.usarGamma ? config.senales.gamma : 1;
const duty = senales.escala255(msg.payload, config.senales.maximo, gamma);
return { payload: senales.dutyAPorcentajePiGpiod(duty), duty };

// =====================================================================
// BLOQUE C7 · Perdida y recuperacion del canal — Raspberry Pi 2
// diagramas/flujo_cliente.md, bloque C7 · consigna Parte 3.6
// ---------------------------------------------------------------------
// Descripcion: registra con marca de tiempo cada evento de conexion,
//   sesion y suscripcion que informa cliente_opcua.js (connection_lost,
//   backoff, connection_reestablished, after_reconnection,
//   subscription_status, keepalive...). Es la evidencia de la prueba de
//   desconexion: que paso, cuando y con que StatusCode.
//   Los KeepAlive se cuentan pero no se imprimen uno por uno (uno por
//   segundo inundaria el registro).
// Entrada: msg.topic = nombre del evento, msg.payload = texto.
// Salida: msg.payload con la linea fechada.
// Excepciones: ninguna.
// =====================================================================
if (msg.topic === 'keepalive') {
    const n = (flow.get('keepalives') || 0) + 1;
    flow.set('keepalives', n);
    node.status({ fill: 'green', shape: 'ring', text: 'KeepAlive x' + n });
    return null;
}
const linea = new Date().toISOString() + ' EVENTO ' + msg.payload;
node.log(linea);
const color = /lost|error|closed|failure|terminated|backoff/.test(msg.topic) ? 'red'
    : /reestablished|after_reconnection|connected|activated|created/.test(msg.topic) ? 'green' : 'yellow';
node.status({ fill: color, shape: 'dot', text: msg.topic });
return { payload: linea };

// =====================================================================
// BLOQUE C6 · Registro en consola — Raspberry Pi 2
// diagramas/flujo_cliente.md, bloque C6 · consigna Parte 3.5
// ---------------------------------------------------------------------
// Descripcion: una vez por segundo imprime la rampa que genera esta placa,
//   la que recibe del servidor (Servidor.Rampa) y su SourceTimestamp, y
//   ademas la antiguedad del dato: si el cable esta desconectado, la
//   antiguedad crece y se ve en la consola que el LED quedo congelado.
// Entrada: msg del inject "C6 · Cada 1 s".
// Salida: msg.payload con la linea.
// Excepciones: ninguna.
// =====================================================================
const generada = flow.get('rampaGenerada');
const recibido = flow.get('servidorRampa');
let ts = 'sin dato';
let antiguedad = '';
if (recibido && recibido.sourceTimestamp) {
    const t = new Date(recibido.sourceTimestamp);
    ts = t.toISOString();
    antiguedad = ' antiguedad=' + (Date.now() - t.getTime()) + ' ms';
}
const linea = 'CLIENTE generada=' + (generada === undefined ? '-' : generada) +
    ' recibida(Servidor.Rampa)=' + (recibido ? recibido.valor : '-') +
    ' SourceTimestamp=' + ts + antiguedad + (recibido ? ' modo=' + recibido.modo : '');
node.log(linea);
return { payload: linea };
